import json,subprocess
def call(n,a):
    r=subprocess.run(["ft2","call",n,json.dumps(a)],capture_output=True,text=True)
    return r.stdout.strip()
print(call("module_new",dict(channels=4,name="leveltest")))
for inst,f in [(1,'kick'),(2,'pad'),(3,'arp'),(4,'bass'),(5,'snare')]:
    print(call("sample_load",dict(path=f"/workspace/samples/{f}.wav",instrument=inst,sample=0)))
print(call("song_set",dict(bpm=150,speed=6)))
print(call("pattern_set_length",dict(pattern=0,rows=32)))
# ch0 kick vol64, ch1 pad chord vol20, ch2 arp vol28, ch3 bass vol44
for r in range(0,32,8):
    print(call("pattern_set_cell",dict(pattern=0,row=r,channel=0,note=61,instrument=1,volume=64)))
for r in range(0,32,16):
    for n in (34,37,40):
        print(call("pattern_set_cell",dict(pattern=0,row=r,channel=1,note=n,instrument=2,volume=20)))
for r in range(0,32,2):
    print(call("pattern_set_cell",dict(pattern=0,row=r,channel=2,note=46,instrument=3,volume=28)))
for r in range(0,32,4):
    print(call("pattern_set_cell",dict(pattern=0,row=r,channel=3,note=34,instrument=4,volume=44)))
print(call("module_render",dict(path="/workspace/build/level.wav",rate=44100,bits=16,loops=1)))
EOF
