    d=np.frombuffer(w.readframes(n),dtype='<i2').astype(np.float32)/32768
    # onset = sharp rise
    e=np.abs(d)
    hits=[i/sr for i in range(1,len(e)) if e[i]>0.03 and e[i-1]<0.01]
    out=[]
    for t in hits:
        if not out or t-out[-1]>0.04: out.append(t)
