{"command":"cd /workspace && python3 - <<'EOF'
import sys; sys.path.insert(0,'/workspace')
import numpy as np
from music import nn_name
import tune_build as T
pats=[]
for fn in T.BUILDERS:
    P=fn(); pats.append((fn.__name__,P.rows,P.cells))
notes=0; bad=[]; chanuse={}; instuse={}
for name,rows,cells in pats:
    for (r,c),v in cells.items():
        notes+=1
        if not (1<=v['note']<=96): bad.append((name,r,c,'note',v['note']))
        if not (1<=v['ins']<=len(T.SAMPLES)): bad.append((name,r,c,'ins',v['ins']))
        if v['vol'] is not None and not (0<=v['vol']<=64): bad.append((name,r,c,'vol',v['vol']))
        chanuse[c]=chanuse.get(c,0)+1
        instuse[v['ins']]=instuse.get(v['ins'],0)+1
print("patterns:",len(pats),"note events:",notes)
print("out-of-range entries:",bad[:5], "count",len(bad))
print("notes per channel:", {T.__dict__[[k for k in T.__dict__ if k.startswith('CH_')][c]]: n for c,n in sorted(chanuse.items())})
print("notes per instrument:", {k: T.SAMPLES[k-1][0] if k-1<len(T.SAMPLES) else k: n for k,n in sorted(instuse.items())})
# pitch range used by pitched instruments (drums excluded)
drums={T.INS['kick'],T.INS['snare'],T.INS['hat'],T.INS['hato'],T.INS['tom']}
lo=[];hi=[]
for name,rows,cells in pats:
    for (r,c),v in cells.items():
        if v['ins'] in drums: continue
        lo.append(v['note']); hi.append(v['note'])
print("pitched note range:", nn_name(min(lo)), "..", nn_name(max(hi)))
# harmony per bar of the arrangement
for name,rows,cells in pats[:1]: pass
print("\narrangement:", [fn.__name__[2:] for fn in T.BUILDERS])
EOF"}

